from typing import Optional, Tuple

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def subtreeWithAllDeepest(self, root: Optional[TreeNode]) -> Optional[TreeNode]:
        def dfs(node: Optional[TreeNode]) -> Tuple[int, Optional[TreeNode]]:
            if not node:
                return 0, None
            d_left, lca_left = dfs(node.left)
            d_right, lca_right = dfs(node.right)
            if d_left == d_right:
                return d_left + 1, node
            if d_left > d_right:
                return d_left + 1, lca_left
            return d_right + 1, lca_right

        return dfs(root)[1]

class Solution {
public:
    pair<int, TreeNode*> dfs(TreeNode* node) {
        if (!node) return {0, nullptr};
        auto [dl, nl] = dfs(node->left);
        auto [dr, nr] = dfs(node->right);
        if (dl == dr) return {dl + 1, node};
        if (dl > dr) return {dl + 1, nl};
        return {dr + 1, nr};
    }

    TreeNode* subtreeWithAllDeepest(TreeNode* root) {
        return dfs(root).second;
    }
};

class Solution {
    static class Result {
        int depth;
        TreeNode node;
        Result(int depth, TreeNode node) {
            this.depth = depth;
            this.node = node;
        }
    }

    private Result dfs(TreeNode node) {
        if (node == null) return new Result(0, null);
        Result left = dfs(node.left);
        Result right = dfs(node.right);
        if (left.depth == right.depth) return new Result(left.depth + 1, node);
        if (left.depth > right.depth) return new Result(left.depth + 1, left.node);
        return new Result(right.depth + 1, right.node);
    }

    public TreeNode subtreeWithAllDeepest(TreeNode root) {
        return dfs(root).node;
    }
}

var subtreeWithAllDeepest = function(root) {
    function dfs(node) {
        if (!node) return [0, null];
        const [dl, nl] = dfs(node.left);
        const [dr, nr] = dfs(node.right);
        if (dl === dr) return [dl + 1, node];
        if (dl > dr) return [dl + 1, nl];
        return [dr + 1, nr];
    }
    return dfs(root)[1];
};
